#include <bits/stdc++.h>
using namespace std;

#define pii pair<int,int>
#define mp make_pair
const int INF = 100000000;
const int MAXN = 6000;

namespace maxflow {
    vector<int> v[MAXN], rev[MAXN], cost[MAXN], cap[MAXN];

    void add_edge(int x, int y, int c, int w) {
        rev[x].push_back((int)v[y].size());
        rev[y].push_back((int)v[x].size());
        v[x].push_back(y);
        v[y].push_back(x);
        cost[x].push_back(w);
        cost[y].push_back(-w);
        cap[x].push_back(c);
        cap[y].push_back(0);
    }

    int dist[MAXN], inq[MAXN], pre_x[MAXN], pre_i[MAXN];

    void spfa(int s) {
        fill(dist, dist + MAXN, 0x3f3f3f3f);
        fill(inq, inq + MAXN, 0);
        pre_x[s] = -1;
        queue<int> q;
        q.push(s);
        dist[s] = 0;
        inq[s] = 1;

        while (!q.empty()) {
            int x = q.front(); q.pop(); inq[x] = 0;
            for (size_t i = 0; i < v[x].size(); ++i) {
                int y = v[x][i];
                int nd = dist[x] + cost[x][i];
                if (dist[y] > nd && cap[x][i]) {
                    dist[y] = nd;
                    pre_x[y] = x;
                    pre_i[y] = i;
                    if (!inq[y]) { inq[y] = 1; q.push(y); }
                }
            }
        }
    }

    int total_flow = 0;

    int dfs(int x, int f) {
        if (pre_x[x] == -1) return f;
        int y = x; x = pre_x[y]; int i = pre_i[y], j = rev[x][i];
        int pushed = dfs(x, min(f, cap[x][i]));
        cap[x][i] -= pushed;
        cap[y][j] += pushed;
        return pushed;
    }

    pair<int,int> solve(int s, int t) {
        int ans = 0, total_cost = 0;
        while (true) {
            spfa(s);
            if (dist[t] > 1e9) break;
            int f = dfs(t, INF);
            total_cost += f * dist[t];
            ans += f;
        }
        return mp(ans, total_cost);
    }
}

int main() {
    int n, m, s = MAXN - 1, t = MAXN - 2;
    int k, c, d;
    cin >> n >> m >> k >> c >> d;

    auto node_id = [](int x, int t) { return t * 52 - 52 + x; };

    for (int i = 0; i < k; ++i) {
        int x; cin >> x;
        maxflow::add_edge(s, node_id(x, 1), 1, 0);
    }

    int k_copy = k;
    for (int i = 0; i < m; ++i) {
        int x, y; cin >> x >> y;
        for (int t = 1; t < 100; ++t) {
            for (int j = 1; j <= k_copy; ++j) {
                maxflow::add_edge(node_id(x, t), node_id(y, t + 1), 1, d * (j + j - 1));
            }
        }
        swap(x, y);
        for (int t = 1; t < 100; ++t) {
            for (int j = 1; j <= k_copy; ++j) {
                maxflow::add_edge(node_id(x, t), node_id(y, t + 1), 1, d * (j + j - 1));
            }
        }
    }

    for (int i = 1; i < 100; ++i) {
        for (int j = 1; j <= n; ++j) {
            maxflow::add_edge(node_id(j, i), node_id(j, i + 1), INF, 0);
        }
        maxflow::add_edge(node_id(1, i), t, INF, c * (i - 1));
    }

    cout << maxflow::solve(s, t).second;
    return 0;
}
